  if intersect:
    // Compute fresnel term (refraction)
    fresnel = fresnel(intersect.normal, intersect.material.refractive_index, light.samples[i].wavelength)

    // Compute contribution of this light sample
    contribution = light_weights[i] * fresnel * intersect '** 2

    // Add to diffuse and specular components
    diffuse_components[i] += contribution
    specular_components[i] += contribution * intersect.material.specular

// Set up ODO (One-Dimensional Occlusion) samples
for each ODO sample in scene:
  // Randomly sample the ODO PDF
