  ODO_index = random choose from 0 to len(ODO_samples) - 1
  ODO_samples = ODO_samples[ODO_index]
  ODO_weights = ODO_weights[ODO_index]

  // Intersect the ray with the ODO sample
  intersect = ray_intersect(scene, ODO_samples[i])

  // If intersection, compute the contribution of this ODO sample
  if intersect:
