import React, { useState, useEffect } from 'react';

const Autocomplete = ({ suggestions, onSelect }) => {
  const [inputValue, setInputValue] = useState('');
  const [suggestionsList, setSuggestionsList] = useState([]);

  useEffect(() => {
    const timeoutId = setTimeout(() => {
      const filteredSuggestions = suggestions.filter((suggestion) => {
        return suggestion.toLowerCase().includes(inputValue.toLowerCase());
      });
      setSuggestionsList(filteredSuggestions);
    }, 500);
    return () => {
      clearTimeout(timeoutId);
    };
  }, [inputValue]);

  const handleInputValueChange = (event) => {
    setInputValue(event.target.value);
  };

  const handleSelect = (suggestion) => {
    setInputValue(suggestion);
    onSelect(suggestion);
  };

  return (
    <div>
      <input type="text" value={inputValue} onChange={handleInputValueChange} />
      <ul>
        {suggestionsList.map((suggestion) => (
          <li key={suggestion} onClick={() => handleSelect(suggestion)}>
            {suggestion}
          </li>
        ))}
      </ul>
    </div>
  );
};

export default Autocomplete;
```
Here's a breakdown of how the component works:

* We use the `useState` hook to keep track of the current input value and the list of suggestions.
* We use the `useEffect` hook to filter the suggestions list whenever the input value changes. We do this by creating a timeout that filters the suggestions list using the `includes` method. We also clear the timeout when the component is unmounted to prevent memory leaks.
* We define two event handlers: `handleInputValueChange` to update the input value, and `handleSelect` to select a suggestion when an item is clicked.
* We render an input field and an unordered list of suggestions. The list is filtered based on the input value.
* When a suggestion is clicked, we update the input value and call the `onSelect` function to notify the parent component that a suggestion has been selected.

