using System.IO;

namespace HttpServerExample
{
    class Program
    {
        static void Main(string[] args)
        {
            // Création d'un nouvel objet HttpListener
            HttpListener listener = new HttpListener();

            // Configuration du serveur
            listener.Prefixes.Add("http://localhost:8080/");

            // Démarre le serveur
            listener.Start();

            Console.WriteLine("Server started. Listening for incoming requests...");

            // Boucle infinie pour accepter les requêtes
            while (true)
            {
                HttpListenerContext context = listener.GetContext();

                // Traitement de la requête
                HttpListenerRequest request = context.Request;
                string method = request.HttpMethod;

                if (method == "GET" && request.Url.AbsolutePath == "/hello")
                {
                    // Affichage du texte "Hello"
                    using (Stream stream = context.Response.OutputStream)
                    {
                        using (StreamWriter writer = new StreamWriter(stream))
                        {
                            writer.WriteLine("Hello");
                        }
                    }
                }
                else
                {
                    // Réponse erreur 404 si la requête n'est pas gérée
                    context.Response.StatusCode = 404;
                    context.Response.StatusDescription = "Not Found";
                }
            }
        }
    }
}
```
Ce code crée un objet `HttpListener` et configure le serveur pour écouter les requêtes sur le port 8080 et sur l'adresse "http://localhost:8080/".

Lorsqu'une requête est reçue, le code vérifie si la requête est une requête GET sur la page "/hello". Si c'est le cas, il affiche le texte "Hello" en réponse.

Si la requête n'est pas gérée, le code répond avec un code d'état 404 (Not Found).

Notez que ce code utilise un blocage infini (`while (true)`) pour accepter les requêtes. Cela signifie que le programme s'arrêtera uniquement lorsque vous le fermez manuellement.

