// Set up the JVMTI agent to listen for class load events
jvmtiAgent.setEventCallbacks(new jvmti.callbacks.ClassLoadEvent() {
    public void classLoad(jvmtiEnv env, jvmtiClassLoadEvent Data) {
        // Get the class being loaded
        jclass clazz = Data.class_;

        // Iterate over the methods in the class
        jmethodId[] methods = env.GetMethodIDs(clazz, null, null);
        for (jmethodId method : methods) {
            // Get the method signature
            jmethodSig sig = env.GetMethodSignature(method);

            // Print the method signature
            System.out.println("Method signature: " + sig);
        }
    }
});
```

