chrome.tabs.onUpdated.addListener(function(tabId, changeInfo, tab) {
  // Get the JSON data from the tab
  chrome.tabs.query({ active: true, currentWindow: true }, function(tabs) {
    var jsonData = tabs[0]. Biography; // or whatever your JSON data is
    // Save the JSON data to the SQLite database
    sqliteSaveData(jsonData);
  });
});

function sqliteSaveData(jsonData) {
  // Create a connection to the SQLite database
  var sqlite3 = require('sqlite3').verbose();
  var db = new sqlite3.Database('my_database.db');

  // Create a table if it doesn't exist
  db.run(`
    CREATE TABLE IF NOT EXISTS json_data (
      id INTEGER PRIMARY KEY,
      json_data TEXT
    );
  `);

  // Insert the JSON data into the table
  db.run(`
    INSERT OR REPLACE INTO json_data (json_data)
    VALUES ($json_data);
  `, { $json_data: JSON.stringify(jsonData) });

  // Close the database connection
  db.close();
}
```
